{"edits":[{"new":"#include "sorting.h"

#include <utility>

void bubble_sort(int* a, size_t n) {
    if (a == nullptr || n < 2) {
        return;
    }
    // Each pass moves the largest remaining element to the end. If a pass
    // performs no swap the array is already ordered, so we can stop early.
    for (size_t end = n; end > 1; --end) {
        bool swapped = false;
        for (size_t i = 1; i < end; ++i) {
            if (a[i - 1] > a[i]) {
                std::swap(a[i - 1], a[i]);
                swapped = true;
            }
        }
        if (!swapped) {
            return;
        }
    }
}

namespace {

// Merges the two sorted runs a[lo, mid) and a[mid, hi) into a[lo, hi),
// using buf as scratch space.
void merge_runs(int* a, int* buf, size_t lo, size_t mid, size_t hi) {
    size_t left = lo;
    size_t right = mid;
    size_t out = lo;

    while (left < mid && right < hi) {
        // Take from the left run on ties to keep the sort stable.
        if (a[right] < a[left]) {
            buf[out++] = a[right++];
        } else {
            buf[out++] = a[left++];
        }
    }
    while (left < mid) {
        buf[out++] = a[left++];
    }
    while (right < hi) {
        buf[out++] = a[right++];
    }
    for (size_t i = lo; i < hi; ++i) {
        a[i] = buf[i];
    }
}

void merge_sort_range(int* a, int* buf, size_t lo, size_t hi) {
    if (hi - lo < 2) {
        return;
    }
    const size_t mid = lo + (hi - lo) / 2;
    merge_sort_range(a, buf, lo, mid);
    merge_sort_range(a, buf, mid, hi);
    merge_runs(a, buf, lo, mid, hi);
}

}  // namespace

void merge_sort(int* a, size_t n) {
    if (a == nullptr || n < 2) {
        return;
    }
    // One scratch buffer for the whole sort; the merge step copies back into
    // a, so the caller's array is the only thing left modified.
    int* buf = new int[n];
    merge_sort_range(a, buf, 0, n);
    delete[] buf;
}
