// Brute force: enumerate all subsequences of the shorter string.
static int brute(const std::string& a, const std::string& b) {
    int best = 0;
    const std::string& s = a.size() <= b.size() ? a : b;
    const std::string& t = a.size() <= b.size() ? b : a;
