```cpp
1: struct Report { std::size_t size = 0; };
2: class ReportParser {
3: public:
4:   Report parse(const std::string& raw) { return Report{raw.size()}; }
5: };
6: class ReportRenderer {
7: public:
8:   void render(const Report& r, std::ostream& out) { out << r.size; }
